-- CrewConvo initial schema (spec section 4).
-- All ids are UUID v7 generated by the application; all timestamps are UTC (timestamptz).

CREATE TABLE workspaces (
    id          uuid PRIMARY KEY,
    name        text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- kind 'system' is an extension of the spec: one per workspace, author of platform notices.
CREATE TABLE members (
    id              uuid PRIMARY KEY,
    workspace_id    uuid NOT NULL REFERENCES workspaces(id),
    kind            text NOT NULL CHECK (kind IN ('human', 'agent', 'system')),
    handle          text NOT NULL,
    display_name    text NOT NULL,
    is_admin        boolean NOT NULL DEFAULT false,
    created_at      timestamptz NOT NULL DEFAULT now(),
    deactivated_at  timestamptz,
    UNIQUE (workspace_id, handle)
);

CREATE TABLE human_credentials (
    member_id      uuid PRIMARY KEY REFERENCES members(id),
    password_hash  text NOT NULL
);

CREATE TABLE sessions (
    token_hash  text PRIMARY KEY,
    member_id   uuid NOT NULL REFERENCES members(id),
    created_at  timestamptz NOT NULL DEFAULT now(),
    expires_at  timestamptz NOT NULL
);

CREATE TABLE agents (
    member_id           uuid PRIMARY KEY REFERENCES members(id),
    origin              text NOT NULL CHECK (origin IN ('builtin', 'external')),
    owner_id            uuid NOT NULL REFERENCES members(id),
    description         text NOT NULL CHECK (length(trim(description)) > 0),
    expertise           text[] NOT NULL DEFAULT '{}',
    status              text NOT NULL DEFAULT 'online' CHECK (status IN ('online', 'offline', 'busy', 'disabled')),
    -- builtin
    model               text,
    system_prompt       text,
    tools               jsonb NOT NULL DEFAULT '[]',
    sandbox_config      jsonb NOT NULL DEFAULT '{}',
    -- external
    token_hash          text,
    delivery            text CHECK (delivery IN ('websocket', 'webhook')),
    webhook_url         text,
    webhook_secret      text,
    -- limits
    max_wake_seconds    integer NOT NULL DEFAULT 300,
    daily_token_budget  bigint
);
CREATE UNIQUE INDEX agents_token_hash_idx ON agents (token_hash) WHERE token_hash IS NOT NULL;

CREATE TABLE conversations (
    id                  uuid PRIMARY KEY,
    workspace_id        uuid NOT NULL REFERENCES workspaces(id),
    kind                text NOT NULL CHECK (kind IN ('channel', 'dm')),
    name                text,
    topic               text,
    visibility          text NOT NULL DEFAULT 'public' CHECK (visibility IN ('public', 'private')),
    created_by          uuid NOT NULL REFERENCES members(id),
    created_at          timestamptz NOT NULL DEFAULT now(),
    archived_at         timestamptz,
    frozen_until_human  boolean NOT NULL DEFAULT false,
    next_seq            bigint NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX conversations_channel_name_idx ON conversations (workspace_id, lower(name)) WHERE kind = 'channel';

CREATE TABLE conversation_members (
    conversation_id  uuid NOT NULL REFERENCES conversations(id),
    member_id        uuid NOT NULL REFERENCES members(id),
    joined_at        timestamptz NOT NULL DEFAULT now(),
    invited_by       uuid REFERENCES members(id),
    last_read_seq    bigint NOT NULL DEFAULT 0,
    PRIMARY KEY (conversation_id, member_id)
);
CREATE INDEX conversation_members_member_idx ON conversation_members (member_id);

CREATE TABLE discussions (
    id               uuid PRIMARY KEY,
    conversation_id  uuid NOT NULL REFERENCES conversations(id),
    thread_root_id   uuid NOT NULL,
    participants     uuid[] NOT NULL,
    round            integer NOT NULL DEFAULT 0,
    max_rounds       integer NOT NULL DEFAULT 3,
    status           text NOT NULL DEFAULT 'running',
    summarizer_id    uuid REFERENCES members(id),
    created_at       timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE wakes (
    id                  uuid PRIMARY KEY,
    agent_id            uuid NOT NULL REFERENCES members(id),
    conversation_id     uuid NOT NULL REFERENCES conversations(id),
    thread_root_id      uuid,
    trigger_message_id  uuid NOT NULL,
    reason              text NOT NULL CHECK (reason IN ('mention', 'dm', 'thread_reply', 'sticky', 'decider', 'discussion_turn')),
    mode                text NOT NULL CHECK (mode IN ('single', 'parallel', 'discussion')),
    discussion_id       uuid REFERENCES discussions(id),
    status              text NOT NULL DEFAULT 'pending'
                        CHECK (status IN ('pending', 'delivered', 'running', 'done', 'timeout', 'failed', 'cancelled')),
    depth               integer NOT NULL,
    chain_root_id       uuid NOT NULL,
    posted_count        integer NOT NULL DEFAULT 0,
    tokens_used         bigint NOT NULL DEFAULT 0,
    private_log         text,
    created_at          timestamptz NOT NULL DEFAULT now(),
    started_at          timestamptz,
    finished_at         timestamptz
);
CREATE INDEX wakes_agent_status_idx ON wakes (agent_id, status, created_at);
CREATE INDEX wakes_chain_idx ON wakes (chain_root_id);
CREATE INDEX wakes_conversation_status_idx ON wakes (conversation_id, status);
CREATE INDEX wakes_trigger_idx ON wakes (trigger_message_id);

CREATE TABLE messages (
    id               uuid PRIMARY KEY,
    conversation_id  uuid NOT NULL REFERENCES conversations(id),
    seq              bigint NOT NULL,
    thread_root_id   uuid REFERENCES messages(id),
    author_id        uuid NOT NULL REFERENCES members(id),
    body             text NOT NULL,
    mentions         uuid[] NOT NULL DEFAULT '{}',
    depth            integer NOT NULL DEFAULT 0,
    chain_root_id    uuid NOT NULL REFERENCES messages(id),
    wake_id          uuid REFERENCES wakes(id),
    created_at       timestamptz NOT NULL DEFAULT now(),
    edited_at        timestamptz,
    deleted_at       timestamptz,
    UNIQUE (conversation_id, seq)
);
CREATE INDEX messages_thread_idx ON messages (thread_root_id, seq) WHERE thread_root_id IS NOT NULL;
CREATE INDEX messages_author_idx ON messages (author_id, created_at);

ALTER TABLE wakes ADD CONSTRAINT wakes_trigger_fk FOREIGN KEY (trigger_message_id) REFERENCES messages(id);

CREATE TABLE reactions (
    message_id  uuid NOT NULL REFERENCES messages(id),
    member_id   uuid NOT NULL REFERENCES members(id),
    emoji       text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (message_id, member_id, emoji)
);

CREATE TABLE summaries (
    id                uuid PRIMARY KEY,
    conversation_id   uuid NOT NULL REFERENCES conversations(id),
    thread_root_id    uuid REFERENCES messages(id),
    covers_up_to_seq  bigint NOT NULL,
    body              text NOT NULL,
    token_count       integer NOT NULL,
    created_at        timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX summaries_scope_idx ON summaries (conversation_id, thread_root_id, created_at DESC);

CREATE TABLE decider_configs (
    id                 uuid PRIMARY KEY,
    workspace_id       uuid NOT NULL REFERENCES workspaces(id),
    name               text NOT NULL,
    protocol           text NOT NULL CHECK (protocol IN ('decisions_api', 'llm_structured')),
    endpoint_url       text NOT NULL,
    api_key_encrypted  text,
    auth_header        text NOT NULL,
    auth_prefix        text NOT NULL DEFAULT '',
    model              text NOT NULL,
    input_field        text NOT NULL DEFAULT 'input',
    timeout_ms         integer NOT NULL DEFAULT 1500,
    t_wake             real NOT NULL DEFAULT 0.6 CHECK (t_wake <= 0.99),
    t_discuss          real NOT NULL DEFAULT 0.7 CHECK (t_discuss <= 0.99),
    max_wake           integer NOT NULL DEFAULT 4,
    extra_headers      jsonb NOT NULL DEFAULT '{}',
    extra_body         jsonb NOT NULL DEFAULT '{}',
    enabled            boolean NOT NULL DEFAULT true,
    priority           integer NOT NULL DEFAULT 0,
    updated_by         uuid REFERENCES members(id),
    updated_at         timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE decisions (
    id                  uuid PRIMARY KEY,
    trigger_message_id  uuid NOT NULL REFERENCES messages(id),
    decider_config_id   uuid REFERENCES decider_configs(id),
    attempts            jsonb NOT NULL DEFAULT '[]',
    request             jsonb,
    response            jsonb,
    woken               uuid[] NOT NULL DEFAULT '{}',
    mode                text,
    latency_ms          integer,
    created_at          timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX decisions_trigger_idx ON decisions (trigger_message_id);

-- One notice per chain when an automatic-conversation limit is hit (spec 6.6).
CREATE TABLE chain_notices (
    chain_root_id  uuid PRIMARY KEY,
    reason         text NOT NULL,
    created_at     timestamptz NOT NULL DEFAULT now()
);
